import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { Readable } from 'node:stream';
import config from '../config/env.js';

/**
 * Storage drivers share one interface so the QR/verification URLs never depend on the provider:
 *   put(key, buffer, contentType) -> void
 *   getStream(key) -> { stream, size }
 *   remove(key) -> void
 * Keys are generated by the server (never from user input).
 */

const SAFE_KEY = /^[a-zA-Z0-9][a-zA-Z0-9/_.-]{0,200}$/;

function assertSafeKey(key) {
  if (!SAFE_KEY.test(key) || key.includes('..') || key.includes('//')) {
    throw new Error('Unsafe storage key');
  }
}

class LocalDriver {
  constructor(root) {
    this.root = root;
  }
  resolve(key) {
    assertSafeKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(this.root + path.sep)) throw new Error('Path traversal blocked');
    return full;
  }
  async put(key, buffer) {
    const full = this.resolve(key);
    await fsp.mkdir(path.dirname(full), { recursive: true });
    await fsp.writeFile(full, buffer, { flag: 'wx', mode: 0o600 });
  }
  async getStream(key) {
    const full = this.resolve(key);
    const stat = await fsp.stat(full);
    return { stream: fs.createReadStream(full), size: stat.size };
  }
  async remove(key) {
    try {
      await fsp.unlink(this.resolve(key));
    } catch (e) {
      if (e.code !== 'ENOENT') throw e;
    }
  }
}

class S3Driver {
  constructor() {
    this.clientPromise = null;
  }
  async client() {
    if (!this.clientPromise) {
      this.clientPromise = import('@aws-sdk/client-s3').then(({ S3Client }) => {
        const opts = { region: config.S3_REGION };
        if (config.S3_ENDPOINT) {
          opts.endpoint = config.S3_ENDPOINT;
          opts.forcePathStyle = true;
        }
        if (config.S3_ACCESS_KEY_ID && config.S3_SECRET_ACCESS_KEY) {
          opts.credentials = { accessKeyId: config.S3_ACCESS_KEY_ID, secretAccessKey: config.S3_SECRET_ACCESS_KEY };
        }
        return new S3Client(opts);
      });
    }
    return this.clientPromise;
  }
  async put(key, buffer, contentType) {
    assertSafeKey(key);
    const { PutObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(
      new PutObjectCommand({
        Bucket: config.S3_BUCKET,
        Key: key,
        Body: buffer,
        ContentType: contentType,
        ServerSideEncryption: config.S3_ENDPOINT ? undefined : 'AES256',
      })
    );
  }
  async getStream(key) {
    assertSafeKey(key);
    const { GetObjectCommand } = await import('@aws-sdk/client-s3');
    const res = await (await this.client()).send(new GetObjectCommand({ Bucket: config.S3_BUCKET, Key: key }));
    const stream = res.Body instanceof Readable ? res.Body : Readable.fromWeb(res.Body);
    return { stream, size: res.ContentLength };
  }
  async remove(key) {
    assertSafeKey(key);
    const { DeleteObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(new DeleteObjectCommand({ Bucket: config.S3_BUCKET, Key: key }));
  }
}

let driver = null;
export function getStorage() {
  if (!driver) driver = config.STORAGE_DRIVER === 's3' ? new S3Driver() : new LocalDriver(config.LOCAL_STORAGE_DIR);
  return driver;
}

/** Test hook. */
export function setStorageDriver(d) {
  driver = d;
}
export { LocalDriver };
